"use client";

import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  DndContext,
  KeyboardSensor,
  PointerSensor,
  closestCenter,
  useSensor,
  useSensors,
  type Announcements,
  type DragEndEvent,
} from "@dnd-kit/core";
import { arrayMove, sortableKeyboardCoordinates } from "@dnd-kit/sortable";
import { AlertCircle, X } from "lucide-react";
import { cn } from "@/lib/utils";
import type {
  CarouselComposerHandle,
  CarouselComposerProps,
  MediaCarouselItem,
  MediaCarouselItemStatus,
} from "./types";
import { useCarouselState } from "./hooks/use-carousel-state";
import { filesToItems } from "./lib/file-intake";
import { clampSources } from "./lib/clamp-sources";
import { aspectToCss, resolveAspect } from "./lib/aspect";
import { mergeLabels } from "./lib/labels";
import { formatDuration as defaultFormatDuration } from "./lib/format-duration";
import { useWarnOnce } from "./hooks/use-warn-once";
import { ItemStatus } from "./parts/item-status";
import { AltField } from "./parts/alt-field";
import { MediaDropzone } from "./parts/media-dropzone";
import { PreviewRail } from "./parts/preview-rail";
import { MainPreview } from "./parts/main-preview";
import { useEditingExtension } from "./hooks/use-editing-extension";
import { useDirection } from "./hooks/use-direction";
import { EditFrame } from "./parts/edit-frame";

/**
 * carousel-composer — a multi-item media composer (Instagram-feed-post
 * semantics): drag-drop / browse one-or-more mixed photo+video files into an
 * ordered, reorderable rail with a main preview, alt text and host-driven upload
 * status. Image editing is injected through `editing` (the
 * `carousel-composer-editing` feature item); the base imports nothing from it.
 */
function CarouselComposerImpl(
  props: CarouselComposerProps,
  ref: React.Ref<CarouselComposerHandle>,
) {
  const {
    value,
    defaultValue,
    onChange,
    maxItems = 10,
    maxFileSizeMb = 50,
    accept,
    acceptMime,
    maxVideoSeconds,
    enableAltText = false,
    maxAltLength: maxAltLengthProp,
    onRetry,
    posterAt,
    formatDuration: formatDurationProp,
    locale = "en",
    dir: dirProp,
    sources,
    aspect = "auto",
    editing: editingProp,
    canEditItem,
    editorProps,
    labels: labelOverrides,
    className,
    revokeOnUnmount,
    onItemAdd,
    onItemRemove,
    onReorder,
    onSelect,
    onEditOpen,
    onEditApply,
    onEditCancel,
    onValidationError,
    onMaxItemsExceeded,
  } = props;

  const merged = useMemo(() => mergeLabels(labelOverrides), [labelOverrides]);
  const { labels } = merged;
  const legacyKeyList = merged.legacyKeys.join(",");
  const warnOnce = useWarnOnce();
  useEffect(() => {
    if (!legacyKeyList) return;
    legacyKeyList.split(",").forEach((key) =>
      warnOnce(
        `legacy-label:${key}`,
        `[CarouselComposer] labels.${key} is a function now (0.2 passed a string template); the string is ignored and the English default is used.`,
      ),
    );
  }, [legacyKeyList, warnOnce]);
  const maxAltLength = Math.max(1, maxAltLengthProp ?? 200);
  const formatDuration = useMemo(
    () => formatDurationProp ?? ((s: number) => defaultFormatDuration(s, locale)),
    [formatDurationProp, locale],
  );
  const acceptKinds = useMemo(
    () => accept ?? ["image" as const, "video" as const],
    [accept],
  );
  // "library" is clamped out — intake is upload-only (drop / browse).
  const uploadEnabled = useMemo(
    () => clampSources(sources).includes("upload"),
    [sources],
  );

  const [ingesting, setIngesting] = useState(false);
  const [errors, setErrors] = useState<string[]>([]);
  const [announce, setAnnounce] = useState("");
  // The live region only speaks when its text changes, so a repeat of the same
  // text alternates a trailing zero-width space.
  const say = useCallback(
    (text: string) => setAnnounce((prev) => (prev === text ? `${text}\u200B` : text)),
    [],
  );
  const rootRef = useRef<HTMLDivElement>(null);
  const dir = useDirection(rootRef, dirProp);
  const mountedRef = useRef(true);
  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);
  // Where focus goes once the element the user acted on is gone.
  const focusTargetRef = useRef<
    { type: "retry"; id: string } | { type: "remove"; id: string; next: string | null } | null
  >(null);

  const { editing, warnOpenWithoutEditing } = useEditingExtension({
    editing: editingProp,
    editorProps,
  });

  const state = useCarouselState({
    canEdit: (it) => canEditItem?.(it) !== false,
    value,
    defaultValue,
    onChange,
    maxItems,
    revokeOnUnmount,
    onItemAdd,
    onItemRemove: (id) => {
      onItemRemove?.(id);
      say(labels.itemRemoved);
    },
    onReorder: (items) => {
      onReorder?.(items);
    },
    onSelect,
    onEditOpen,
    onEditApply,
    onEditCancel,
    onMaxItemsExceeded: (attempted, max) => {
      onMaxItemsExceeded?.(attempted, max);
      const msg = labels.maxReached(max);
      // The error list below is a role="alert" region and announces this once.
      setErrors((prev) => (prev.includes(msg) ? prev : [...prev, msg]));
    },
  });

  // Announce each item's status or error CHANGE (never the statuses present at
  // mount or on first sight of an item, never progress ticks).
  const prevStatuses = useRef<Map<
    string,
    { status: MediaCarouselItemStatus | undefined; error: string | undefined }
  > | null>(null);
  useEffect(() => {
    const prev = prevStatuses.current;
    const next = new Map<
      string,
      { status: MediaCarouselItemStatus | undefined; error: string | undefined }
    >();
    const spoken: string[] = [];
    state.items.forEach((it, i) => {
      next.set(it.id, { status: it.status, error: it.error });
      const before = prev?.get(it.id);
      if (
        before &&
        it.status &&
        (before.status !== it.status || before.error !== it.error)
      ) {
        spoken.push(
          labels.uploadStatus({
            status: it.status,
            position: i + 1,
            total: state.items.length,
            error: it.error,
          }),
        );
      }
    });
    prevStatuses.current = next;
    if (spoken.length > 0) say(spoken.join(". "));
  }, [state.items, labels, say]);

  // Open edit that can no longer happen: the item left `items`, `editing` was
  // removed, or `canEditItem` now refuses it. Close it (fires onEditCancel once).
  const { editingId, cancelEdit } = state;
  useEffect(() => {
    if (editingId === null) return;
    const item = state.items.find((it) => it.id === editingId);
    const stillValid =
      editing !== undefined &&
      item !== undefined &&
      item.kind === "image" &&
      canEditItem?.(item) !== false;
    if (!stillValid) cancelEdit();
  }, [editingId, state.items, editing, canEditItem, cancelEdit]);

  // Hand focus on after Retry / Remove unmount the focused control. Only acts when
  // focus was lost to <body>, so it never pulls focus from where the user went.
  useEffect(() => {
    const target = focusTargetRef.current;
    const root = rootRef.current;
    if (!target || !root) return;
    const item = state.items.find((it) => it.id === target.id);
    const find = (attr: string, id: string) =>
      Array.from(root.querySelectorAll<HTMLElement>(`[${attr}]`)).find(
        (el) => el.getAttribute(attr) === id,
      );
    const lost = () =>
      document.activeElement === null || document.activeElement === document.body;
    if (target.type === "retry") {
      if (!item) {
        focusTargetRef.current = null;
        return;
      }
      if (item.status === "error") return;
      focusTargetRef.current = null;
      if (!lost()) return;
      (find("data-progress-for", item.id) ?? find("data-thumb-select", item.id))?.focus();
      return;
    }
    if (item) return;
    focusTargetRef.current = null;
    if (!lost()) return;
    const el = target.next
      ? find("data-thumb-select", target.next)
      : root.querySelector<HTMLElement>("[data-dropzone-browse]");
    el?.focus();
  }, [state.items]);

  // Closing the edit (Done, Cancel or an automatic close) removes the panel and the focus
  // with it. Hand focus back to the Edit button, else the selected thumb, but only if it
  // was lost: never pull it from where the user went.
  const isEditingNow =
    editing !== undefined && state.editingId !== null && state.editingItem !== null;
  const wasEditingRef = useRef(false);
  const selectedIdNow = state.selectedId;
  useEffect(() => {
    const was = wasEditingRef.current;
    wasEditingRef.current = isEditingNow;
    if (!was || isEditingNow) return;
    const root = rootRef.current;
    if (!root) return;
    const active = document.activeElement;
    if (active && active !== document.body) return;
    const thumb = Array.from(root.querySelectorAll<HTMLElement>("[data-thumb-select]")).find(
      (el) => el.getAttribute("data-thumb-select") === selectedIdNow,
    );
    (root.querySelector<HTMLElement>("[data-edit-button]") ?? thumb)?.focus();
  }, [isEditingNow, selectedIdNow]);

  const resolvedAspect = useMemo(
    () => resolveAspect(state.items, aspect),
    [state.items, aspect],
  );

  const addFiles = async (files: File[] | FileList) => {
    setErrors([]);
    setIngesting(true);
    try {
      const res = await filesToItems(files, {
        accept: acceptKinds,
        acceptMime,
        maxFileSizeMb,
        maxVideoSeconds,
        posterAt,
        errors: labels.errors,
      });
      if (!mountedRef.current) {
        // Unmounted while reading the files: release what intake created.
        res.items.forEach((it) => {
          URL.revokeObjectURL(it.url);
          if (it.posterUrl) URL.revokeObjectURL(it.posterUrl);
        });
        return;
      }
      res.errors.forEach((err) => onValidationError?.(err));
      if (res.errors.length > 0) {
        setErrors((prev) => [...prev, ...res.errors.map((e) => e.message)]);
      }
      // addItems caps to maxItems synchronously + fires onMaxItemsExceeded.
      if (res.items.length > 0) {
        const before = state.getItems().length;
        state.addItems(res.items);
        // Count what was kept, not what was offered (the cap may drop some).
        const added = state.getItems().length - before;
        if (added > 0) say(labels.itemsAdded(added));
      }
    } finally {
      if (mountedRef.current) setIngesting(false);
    }
  };
  // The handle calls the latest closure, so label / limit changes apply.
  const addFilesRef = useRef(addFiles);
  useEffect(() => {
    addFilesRef.current = addFiles;
  });

  const handleRetry = onRetry
    ? (item: MediaCarouselItem) => {
        focusTargetRef.current = { type: "retry", id: item.id };
        onRetry(item);
      }
    : undefined;

  const handleRemove = (id: string) => {
    const list = state.getItems();
    const idx = list.findIndex((it) => it.id === id);
    const neighbour = idx < 0 ? undefined : (list[idx + 1] ?? list[idx - 1]);
    focusTargetRef.current = { type: "remove", id, next: neighbour?.id ?? null };
    state.removeItem(id);
  };

  // The dismiss button is about to unmount; keep focus in the component.
  const dismissErrors = () => {
    const root = rootRef.current;
    const candidates = [
      "[data-dropzone-browse]",
      "[data-dropzone-add-more]",
      `[data-thumb-select="${state.selectedId ?? ""}"]`,
    ];
    for (const selector of candidates) {
      const el = root?.querySelector<HTMLElement>(selector);
      if (!el || (el as HTMLButtonElement).disabled) continue;
      el.focus();
      if (document.activeElement === el) break;
    }
    setErrors([]);
  };

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 4 } }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    }),
  );

  // Rebuilt when `labels.drag` changes, so a locale switch reaches the announcements.
  const dragLabels = labels.drag;
  const { getItems } = state;
  // Final index of the item just dropped, set in onDragEnd. The announcement can run
  // after the reorder, when the over item's position has already shifted.
  const droppedRef = useRef<{ id: string | number; position: number } | null>(null);
  const dndAnnouncements: Announcements = useMemo(() => {
    const pos = (id: string | number) =>
      getItems().findIndex((it) => it.id === id) + 1;
    const total = () => getItems().length;
    return {
      onDragStart: ({ active }) => dragLabels.pickedUp(pos(active.id), total()),
      onDragOver: ({ active, over }) =>
        over ? dragLabels.over(pos(active.id), pos(over.id), total()) : "",
      onDragEnd: ({ active, over }) => {
        const dropped = droppedRef.current;
        droppedRef.current = null;
        if (!over) return dragLabels.droppedInPlace(pos(active.id));
        const final = dropped && dropped.id === active.id ? dropped.position : pos(over.id);
        return dragLabels.dropped(final, total());
      },
      onDragCancel: ({ active }) => dragLabels.cancelled(pos(active.id)),
    };
  }, [dragLabels, getItems]);

  const onDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over || active.id === over.id) return;
    const items = getItems();
    const oldIndex = items.findIndex((it) => it.id === active.id);
    const newIndex = items.findIndex((it) => it.id === over.id);
    if (oldIndex < 0 || newIndex < 0) return;
    droppedRef.current = { id: active.id, position: newIndex + 1 };
    state.reorder(arrayMove(items, oldIndex, newIndex));
  };

  const {
    removeItem,
    updateItem,
    select: selectItem,
    openEditor: openEditorState,
    reset: resetItems,
  } = state;
  useImperativeHandle(
    ref,
    (): CarouselComposerHandle => ({
      getItems: () => getItems().map((it) => ({ ...it })),
      export: async () => getItems().map((it) => ({ ...it })),
      addFiles: (files) => addFilesRef.current(files),
      removeItem,
      updateItem,
      select: selectItem,
      openEditor: (id: string) => {
        if (!editing) {
          warnOpenWithoutEditing(id);
          return;
        }
        openEditorState(id);
      },
      reset: resetItems,
    }),
    [removeItem, updateItem, selectItem, openEditorState, resetItems, getItems, editing, warnOpenWithoutEditing],
  );

  const isEmpty = state.items.length === 0;
  const isEditing =
    editing !== undefined && state.editingId !== null && state.editingItem !== null;
  const EditingPanel = editing?.Panel;
  const sel = state.selectedItem;
  const canEdit =
    editing !== undefined &&
    sel !== null &&
    sel.kind === "image" &&
    canEditItem?.(sel) !== false;
  const canAddMore = uploadEnabled && state.items.length < maxItems;

  return (
    <div ref={rootRef} dir={dirProp} className={cn("flex flex-col gap-3", className)}>
      {isEmpty ? (
        uploadEnabled ? (
          <MediaDropzone
            variant="empty"
            accept={acceptKinds}
            acceptMime={acceptMime}
            maxItems={maxItems}
            busy={ingesting}
            labels={labels}
            onFiles={addFiles}
          />
        ) : null
      ) : isEditing && EditingPanel ? (
        <EditFrame key={state.editingItem!.id} label={labels.edit}>
        <EditingPanel
          item={state.editingItem!}
          aspect={resolvedAspect}
          editorProps={editorProps}
          labels={{
            editDone: labels.editDone,
            editCancel: labels.editCancel,
            editSaving: labels.editSaving,
            editError: labels.editError,
          }}
          onApply={state.applyEdit}
          onCancel={state.cancelEdit}
        />
        </EditFrame>
      ) : (
        <MainPreview
          item={state.selectedItem}
          aspectCss={aspectToCss(resolvedAspect)}
          canEdit={canEdit}
          editingEnabled={editing !== undefined}
          labels={labels}
          onEdit={() =>
            state.selectedItem && state.openEditor(state.selectedItem.id)
          }
        />
      )}

      {!isEmpty && !isEditing ? (
        <>
          <ItemStatus
            item={state.selectedItem}
            labels={labels}
            position={state.items.findIndex((it) => it.id === state.selectedId) + 1}
            total={state.items.length}
            onRetry={handleRetry}
          />
          {enableAltText ? (
            <AltField
              item={state.selectedItem}
              maxLength={maxAltLength}
              labels={labels}
              onChange={(id, alt) =>
                state.updateItem(id, { alt: alt === "" ? undefined : alt })
              }
            />
          ) : null}
        </>
      ) : null}

      {errors.length > 0 ? (
        <div
          role="alert"
          className="flex items-start gap-2 rounded-md border border-destructive/40 bg-destructive/10 px-3 py-2 text-sm text-foreground"
        >
          <AlertCircle
            className="mt-0.5 size-4 shrink-0 text-destructive"
            aria-hidden
          />
          <ul className="flex-1 space-y-0.5">
            {errors.map((msg, i) => (
              <li key={i}>{msg}</li>
            ))}
          </ul>
          <button
            type="button"
            aria-label={labels.dismissErrors}
            onClick={dismissErrors}
            className="shrink-0 rounded p-0.5 text-muted-foreground transition hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            <X className="size-4" aria-hidden />
          </button>
        </div>
      ) : null}

      {!isEmpty ? (
        <DndContext
          sensors={sensors}
          collisionDetection={closestCenter}
          accessibility={{
            announcements: dndAnnouncements,
            screenReaderInstructions: { draggable: labels.drag.instructions },
          }}
          onDragEnd={onDragEnd}
        >
          <PreviewRail
            items={state.items}
            selectedId={state.selectedId}
            disabled={isEditing}
            canAddMore={canAddMore}
            busy={ingesting}
            accept={acceptKinds}
            acceptMime={acceptMime}
            maxItems={maxItems}
            labels={labels}
            formatDuration={formatDuration}
            onRetry={handleRetry}
            onSelect={state.select}
            onRemove={handleRemove}
            onFiles={addFiles}
            dir={dir}
          />
        </DndContext>
      ) : null}

      <output aria-live="polite" className="sr-only">
        {announce}
      </output>
    </div>
  );
}

export const CarouselComposer = forwardRef(CarouselComposerImpl);
CarouselComposer.displayName = "CarouselComposer";

// ─── Tail type re-exports (cross-procomp consumers) ──────────────────────────
// Procomps that compose carousel-composer must import these types from
// THIS component-file path, not `./types`: the shadcn path rewriter resolves a
// barrel/directory import to this `.tsx` file but mangles `/types` subpaths
// (F-01). Mirrors media-editor's tail band.
export type {
  MediaCarouselItem,
  MediaKind,
  MediaCarouselSource,
  MediaCarouselError,
  CarouselComposerProps,
  CarouselComposerHandle,
  CarouselComposerLabels,
  CarouselAspectRatio,
  CarouselExportMeta,
  CarouselEditingExtension,
  CarouselEditorPanelProps,
  ApplyEditPatch,
  MediaCarouselItemPatch,
  MediaCarouselItemStatus,
  MediaCarouselErrorKind,
  CarouselComposerLabelsInput,
  CarouselComposerErrorLabels,
  CarouselComposerDragLabels,
} from "./types";
export {
  defaultCarouselComposerLabels,
  PLATFORM_SAFE_MIME,
  DEFAULT_CAROUSEL_LABELS,
} from "./types";

export { CarouselComposer } from "./carousel-composer";

export type {
  MediaCarouselItem,
  MediaKind,
  MediaCarouselSource,
  MediaCarouselError,
  CarouselComposerProps,
  CarouselComposerHandle,
  CarouselComposerLabels,
  CarouselAspectRatio,
  CarouselExportMeta,
  CarouselEditingExtension,
  CarouselEditorPanelProps,
  ApplyEditPatch,
  MediaCarouselItemPatch,
  MediaCarouselItemStatus,
  MediaCarouselErrorKind,
  CarouselComposerLabelsInput,
  CarouselComposerErrorLabels,
  CarouselComposerDragLabels,
} from "./types";
export {
  defaultCarouselComposerLabels,
  PLATFORM_SAFE_MIME,
  DEFAULT_CAROUSEL_LABELS,
} from "./types";

// Headless state primitive — for consumers that recompose the surface from the
// parts below and need the model (items / selection / editing / URL lifecycle).
export { useCarouselState } from "./hooks/use-carousel-state";
export type {
  UseCarouselStateOptions,
  UseCarouselStateResult,
  CarouselStateCallbacks,
} from "./hooks/use-carousel-state";

// Public parts — for sealed-folder consumers that want to recompose the surface.
export { MediaDropzone } from "./parts/media-dropzone";
export type { MediaDropzoneProps } from "./parts/media-dropzone";
export { PreviewRail } from "./parts/preview-rail";
export type { PreviewRailProps } from "./parts/preview-rail";
export { RailThumb } from "./parts/rail-thumb";
export type { RailThumbProps } from "./parts/rail-thumb";
export { MainPreview } from "./parts/main-preview";
export type { MainPreviewProps } from "./parts/main-preview";

// Image editing is the opt-in `@ilinxa/carousel-composer-editing` item
// (`features/editing/`). The base barrel never exports it, so the base installs
// without media-editor.

// @ilinxa/carousel-composer 0.3.0

import type { ComponentType } from "react";

// carousel-composer 0.3.0 — the base imports NOTHING from media-editor. Image
// editing is an opt-in feature item (`@ilinxa/carousel-composer-editing`,
// installed into `features/editing/`) passed in through the `editing` prop.
// The editor-shaped fields on an item (`editorState`, `exportMeta`) are typed
// here without media-editor's types; the add-on exports typed readers
// (`editorStateOf`, `exportMetaOf`).

export type MediaKind = "image" | "video";
/** `"library"` is accepted for forward compatibility and ignored: intake is upload-only. */
export type MediaCarouselSource = "upload" | "library";

/** The carousel's shared frame aspect — the same values as media-editor's `AspectRatio`. */
export type CarouselAspectRatio = "9:16" | "1:1" | "16:9" | "4:5" | "free";
/** @deprecated Use `CarouselAspectRatio` (0.2 re-exported media-editor's `AspectRatio` from this file). */
export type AspectRatio = CarouselAspectRatio;

/**
 * Image and video types the ilinxa Social Platform accepts (no WebM). Pass it as
 * `acceptMime={PLATFORM_SAFE_MIME}`; the default stays permissive (any `image/*`
 * or `video/*`).
 */
export const PLATFORM_SAFE_MIME: readonly string[] = [
  "image/jpeg",
  "image/png",
  "image/webp",
  "image/gif",
  "video/mp4",
  "video/quicktime",
];

export type MediaCarouselErrorKind =
  | "unsupported-type"
  | "file-too-large"
  | "video-too-long";

/** A file refused at intake. The cap has its own `onMaxItemsExceeded` channel. */
export interface MediaCarouselError {
  kind: MediaCarouselErrorKind;
  /** The message shown to the user, from `labels.errors`. */
  message: string;
  file?: File;
  /** `"video-too-long"`: the video's length and the limit, in seconds. */
  durationSeconds?: number;
  maxSeconds?: number;
}

/** Host-owned upload state. The host uploads on add and sets these on the item. */
export type MediaCarouselItemStatus = "pending" | "uploading" | "uploaded" | "error";

/**
 * What the carousel itself reads from an editor export. The editing add-on stores
 * media-editor's full `ExportMetadata` here (a superset); read it typed with the
 * add-on's `exportMetaOf(item)`.
 */
export interface CarouselExportMeta {
  width: number;
  height: number;
  mimeType: string;
  durationMs?: number;
}

/**
 * One item in the carousel. `url` is the CURRENT displayable source — an object
 * URL for local/edited media, or a remote URL (re-edit seeds, uploaded media).
 */
export interface MediaCarouselItem {
  id: string;
  kind: MediaKind;
  url: string;
  /** Present for local / edited media; absent for a remote-only item. For an added video it is the original `File`, never re-encoded. */
  blob?: Blob;
  /**
   * Editable layers from the last edit (images only), written and read by the
   * editing add-on — media-editor's `MediaEditorState`. Opaque to the base; read
   * it with `editorStateOf(item)` from `@/components/carousel-composer/features/editing`.
   */
  editorState?: unknown;
  /**
   * The blob behind `editorState`'s image, kept at edit-apply so a re-edit can
   * re-open it after the previous editor's object URLs are revoked. In-memory only.
   */
  sourceBlob?: Blob;
  /** From the last edit's export. */
  exportMeta?: CarouselExportMeta;
  width?: number;
  height?: number;
  fileName?: string;

  /** Alt text (images). Edited in the preview when `enableAltText` is set. */
  alt?: string;
  /** Upload state, set by the host (controlled `value`, or the handle's `updateItem`). */
  status?: MediaCarouselItemStatus;
  /** Upload progress from 0 to 1, shown while `status` is `"uploading"`. */
  progress?: number;
  /** Error text for `status: "error"`, shown with a Retry when `onRetry` is wired. */
  error?: string;
  /** Video length in seconds, read on add. */
  duration?: number;
  /** A JPEG frame grabbed on add (videos, `posterAt`). */
  posterBlob?: Blob;
  /** Object URL of `posterBlob`, created and revoked by the carousel. */
  posterUrl?: string;
}

/** Fields a host may change through the handle's `updateItem`. */
export type MediaCarouselItemPatch = Partial<Omit<MediaCarouselItem, "id" | "kind">>;

/** What an edit-apply writes onto the item. */
export interface ApplyEditPatch {
  url: string;
  blob?: Blob;
  editorState?: unknown;
  sourceBlob?: Blob;
  exportMeta?: CarouselExportMeta;
  width?: number;
  height?: number;
}

// ─── Labels ──────────────────────────────────────────────────────────────────

export interface CarouselComposerErrorLabels {
  /** A file whose type is not an image or video, or not in `acceptMime`. */
  unsupportedType: (info: { file: File; type: string }) => string;
  /** An image or video when `accept` leaves that kind out. */
  kindNotAccepted: (info: { file: File; kind: MediaKind }) => string;
  fileTooLarge: (info: { file: File; sizeMb: number; maxMb: number }) => string;
  videoTooLong: (info: { file: File; seconds: number; maxSeconds: number }) => string;
}

/** Drag-and-drop screen-reader text. Positions are 1-based. */
export interface CarouselComposerDragLabels {
  /** How to drag with the keyboard — read when a drag handle gets focus. */
  instructions: string;
  pickedUp: (position: number, total: number) => string;
  over: (position: number, overPosition: number, total: number) => string;
  dropped: (position: number, total: number) => string;
  droppedInPlace: (position: number) => string;
  cancelled: (position: number) => string;
}

export interface CarouselComposerLabels {
  dropzoneTitle: string;
  dropzoneBrowse: string;
  dropzoneHint: (max: number) => string;
  /** Shown in the dropzone while files are read. */
  dropzoneBusy: string;
  addMore: string;
  /** The preview's Edit button (only with the editing add-on). */
  edit: string;
  editDone: string;
  editCancel: string;
  editSaving: string;
  editError: string;
  /**
   * @deprecated Use `removeItem`. Still names the rail's remove buttons when `removeItem` is not
   * passed (0.2 translations keep working); otherwise unused.
   */
  remove: string;
  /** Accessible name of a rail thumb's remove button. `position` is 1-based. */
  removeItem: (info: { position: number; total: number; kind: MediaKind }) => string;
  /** The rail's drag handle. */
  reorderHint: string;
  maxReached: (max: number) => string;
  /** Caption on a video in the preview when the editing add-on is installed. */
  videoNotEditable: string;
  finishEditingHint: string;
  /** Name of a rail thumb. `position` is 1-based. The default adds `pending` / `uploading` / `error` and the alt text. */
  itemAria: (info: {
    position: number;
    total: number;
    kind: MediaKind;
    alt?: string;
    status?: MediaCarouselItemStatus;
  }) => string;
  /** The error panel's dismiss button. */
  dismissErrors: string;
  /** Announced after files are added. */
  itemsAdded: (count: number) => string;
  /** Announced after an item is removed. */
  itemRemoved: string;
  drag: CarouselComposerDragLabels;
  /** The alt-text field (`enableAltText`). */
  altLabel: string;
  altPlaceholder: string;
  altCounter: (length: number, max: number) => string;
  /** Accessible name of a progress indicator. `progress` is 0–1; `position` is 1-based. */
  uploadProgress: (progress: number, info: { position: number; total: number }) => string;
  /** Shown for `status: "error"` when the item has no `error` text. */
  uploadFailed: string;
  retry: string;
  /** Announced (politely) when an item's `status` changes. `position` is 1-based. */
  uploadStatus: (info: {
    status: MediaCarouselItemStatus;
    position: number;
    total: number;
    error?: string;
  }) => string;
  /** Accessible name of a video's duration badge, e.g. "Duration 0:45". */
  durationLabel: (formatted: string) => string;
  errors: CarouselComposerErrorLabels;
}

/** What `labels` accepts: any subset; `errors` and `drag` merge key by key. */
export type CarouselComposerLabelsInput = Partial<
  Omit<CarouselComposerLabels, "errors" | "drag">
> & {
  errors?: Partial<CarouselComposerErrorLabels>;
  drag?: Partial<CarouselComposerDragLabels>;
};

/** English defaults. Partial overrides merge over these (`errors` / `drag` key by key). */
export const defaultCarouselComposerLabels: CarouselComposerLabels = {
  dropzoneTitle: "Drag photos & videos here",
  dropzoneBrowse: "Browse",
  dropzoneHint: (max) => `or drop up to ${max} files`,
  dropzoneBusy: "Adding media…",
  addMore: "Add more",
  edit: "Edit",
  editDone: "Done",
  editCancel: "Cancel",
  editSaving: "Saving…",
  editError: "Couldn't save your edit. Try again.",
  remove: "Remove",
  removeItem: ({ position, total }) => `Remove item ${position} of ${total}`,
  reorderHint: "Drag to reorder",
  maxReached: (max) => `Maximum ${max} items reached`,
  videoNotEditable: "Video editing isn't available.",
  finishEditingHint: "Finish editing to reorder or add media",
  itemAria: ({ position, total, kind, alt, status }) => {
    const state =
      status === "uploading" || status === "error" || status === "pending"
        ? `, ${status}`
        : "";
    return `Media item ${position} of ${total}, ${kind}${state}${alt ? `: ${alt}` : ""}`;
  },
  dismissErrors: "Dismiss",
  itemsAdded: (count) => (count === 1 ? "1 item added" : `${count} items added`),
  itemRemoved: "Item removed",
  drag: {
    instructions:
      "To pick up an item, press the space bar. While dragging, use the arrow keys to move it. Press space again to drop it in its new position, or press escape to cancel.",
    pickedUp: (position) => `Picked up item ${position}.`,
    over: (position, overPosition) =>
      `Item ${position} over position ${overPosition}.`,
    dropped: (position, total) => `Item dropped at position ${position} of ${total}.`,
    droppedInPlace: (position) => `Item ${position} dropped.`,
    cancelled: (position) => `Reorder cancelled; item ${position} returned.`,
  },
  altLabel: "Alt text",
  altPlaceholder: "Describe this image for people who can't see it",
  altCounter: (length, max) => `${length}/${max}`,
  uploadProgress: (progress, { position, total }) =>
    `Item ${position} of ${total} uploading, ${Math.round(progress * 100)}%`,
  uploadFailed: "Upload failed",
  retry: "Retry",
  uploadStatus: ({ status, position, total, error }) => {
    switch (status) {
      case "pending":
        return `Item ${position} of ${total} waiting to upload`;
      case "uploading":
        return `Item ${position} of ${total} uploading`;
      case "uploaded":
        return `Item ${position} of ${total} uploaded`;
      case "error":
        return `Item ${position} of ${total} failed to upload${error ? `: ${error}` : ""}`;
    }
  },
  durationLabel: (formatted) => `Duration ${formatted}`,
  errors: {
    unsupportedType: ({ type }) => `Unsupported file type: ${type || "unknown"}`,
    kindNotAccepted: ({ kind }) =>
      `${kind === "image" ? "Image" : "Video"} files are not accepted here.`,
    fileTooLarge: ({ sizeMb, maxMb }) =>
      `File is ${sizeMb.toFixed(1)} MB — maximum is ${maxMb} MB.`,
    videoTooLong: ({ seconds, maxSeconds }) =>
      `Video is ${Math.round(seconds)} s — maximum is ${maxSeconds} s.`,
  },
};

/** @deprecated Use `defaultCarouselComposerLabels` (0.3.0 turned the three `{max}` / `{n}` templates into functions). */
export const DEFAULT_CAROUSEL_LABELS = defaultCarouselComposerLabels;

// ─── Editing seam (feature item) ──────────────────────────────────────────────

/** What the editing panel receives. A superset of a `renderEditor({ item, onApply, onCancel })` slot. */
export interface CarouselEditorPanelProps {
  item: MediaCarouselItem;
  aspect: CarouselAspectRatio;
  labels: Pick<CarouselComposerLabels, "editDone" | "editCancel" | "editSaving" | "editError">;
  /** `CarouselComposerProps.editorProps`, passed through untouched. */
  editorProps?: Readonly<Record<string, unknown>>;
  /** Commit an edit: replaces the item's `url` / `blob` and stores the edit fields. */
  onApply: (id: string, patch: ApplyEditPatch) => void;
  onCancel: () => void;
}

/**
 * Image editing, injected: `editing={carouselEditing}` from
 * `@/components/carousel-composer/features/editing` (registry item
 * `@ilinxa/carousel-composer-editing`), or your own `{ Panel }`. Without it the
 * preview has no Edit button.
 */
export interface CarouselEditingExtension {
  Panel: ComponentType<CarouselEditorPanelProps>;
}

// ─── Props / handle ───────────────────────────────────────────────────────────

export interface CarouselComposerProps {
  // value
  value?: MediaCarouselItem[];
  defaultValue?: MediaCarouselItem[];
  onChange?: (items: MediaCarouselItem[]) => void;

  // capability dials
  /** Default 10. */
  maxItems?: number;
  /** Default 50. */
  maxFileSizeMb?: number;
  /** Which kinds are accepted. Default `["image", "video"]`. */
  accept?: MediaKind[];
  /**
   * Exact MIME allow-list, also used for the file input's `accept`. Default: any
   * `image/*` / `video/*` (filtered by `accept`). `PLATFORM_SAFE_MIME` refuses WebM.
   */
  acceptMime?: readonly string[];
  /** Refuse videos longer than this, in seconds (read from the file on add). Default: no limit. */
  maxVideoSeconds?: number;
  /** Default `["upload"]`; `"library"` is ignored. */
  sources?: MediaCarouselSource[];
  /** Default `"auto"`: derived from item 1's dimensions. */
  aspect?: CarouselAspectRatio | "auto";

  // editing (feature item)
  /** Image editing add-on. Without it there is no Edit button and `openEditor` does nothing (one dev warning). */
  editing?: CarouselEditingExtension;
  /** Which items can be edited. Default: images. A video is never editable (its output is the original file). */
  canEditItem?: (item: MediaCarouselItem) => boolean;
  /**
   * Passed to the editing panel untouched — with the add-on, media-editor props
   * (`enabledTools`, `stickers`, `fonts`, `colorPresets`, `filterPresets`, `labels`);
   * type it with the add-on's `CarouselEditorProps`. Ignored without `editing` (one dev warning).
   */
  editorProps?: Readonly<Record<string, unknown>>;

  // alt text
  /** Show an alt-text field for the selected image. Default false. */
  enableAltText?: boolean;
  /** Default 200. */
  maxAltLength?: number;

  // upload status
  /** Shows a Retry on an item with `status: "error"`. */
  onRetry?: (item: MediaCarouselItem) => void;

  // video
  /** Seconds into a video to grab its poster frame; `false` = no poster. Default 0.5. */
  posterAt?: number | false;
  /** Formats a video's duration badge. Default `m:ss` (`h:mm:ss` past an hour), digits in `locale`. */
  formatDuration?: (seconds: number) => string;
  /** BCP 47 tag for the default duration format. Default `"en"`. */
  locale?: string;
  /** Text direction (the rail mirrors in RTL). Default: read from the element after mount. */
  dir?: "ltr" | "rtl";

  labels?: CarouselComposerLabelsInput;
  className?: string;
  /**
   * Revoke object URLs this component created when it unmounts. Default true.
   * Set false ONLY when a host preserves the live items across remounts and
   * takes over final cleanup (e.g. content-composer's carousel cache).
   */
  revokeOnUnmount?: boolean;

  // events
  onItemAdd?: (item: MediaCarouselItem) => void;
  onItemRemove?: (id: string) => void;
  onReorder?: (items: MediaCarouselItem[]) => void;
  onSelect?: (id: string | null) => void;
  onEditOpen?: (id: string) => void;
  onEditApply?: (item: MediaCarouselItem) => void;
  onEditCancel?: (id: string) => void;
  onValidationError?: (error: MediaCarouselError) => void;
  onMaxItemsExceeded?: (attempted: number, max: number) => void;
}

export interface CarouselComposerHandle {
  getItems: () => MediaCarouselItem[];
  /**
   * Resolves a copy of the COMMITTED ordered items (edits already flattened). An
   * open, unapplied edit is not included — gate publish while editing.
   */
  export: () => Promise<MediaCarouselItem[]>;
  /** Same path as the dropzone, with the current props. Resolves once the files are read and added. */
  addFiles: (files: File[] | FileList) => Promise<void>;
  removeItem: (id: string) => void;
  /** Patch an item (upload `status` / `progress` / `error`, the uploaded `url`, `alt`…). */
  updateItem: (id: string, patch: MediaCarouselItemPatch) => void;
  select: (id: string | null) => void;
  /** Open the editor for an item. Needs `editing`; videos and items `canEditItem` refuses are ignored (dev warning). */
  openEditor: (id: string) => void;
  /** Revoke all owned object URLs and clear the items. (Unmount revokes owned URLs too, unless `revokeOnUnmount={false}`.) */
  reset: () => void;
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import type {
  ApplyEditPatch,
  MediaCarouselItem,
  MediaCarouselItemPatch,
} from "../types";
import { useControllableState } from "./use-controllable-state";
import { useWarnOnce } from "./use-warn-once";

export interface CarouselStateCallbacks {
  onItemAdd?: (item: MediaCarouselItem) => void;
  onItemRemove?: (id: string) => void;
  onReorder?: (items: MediaCarouselItem[]) => void;
  onSelect?: (id: string | null) => void;
  onEditOpen?: (id: string) => void;
  onEditApply?: (item: MediaCarouselItem) => void;
  onEditCancel?: (id: string) => void;
  onMaxItemsExceeded?: (attempted: number, max: number) => void;
}

export interface UseCarouselStateOptions extends CarouselStateCallbacks {
  value?: MediaCarouselItem[];
  defaultValue?: MediaCarouselItem[];
  onChange?: (items: MediaCarouselItem[]) => void;
  maxItems: number;
  /**
   * Revoke owned object URLs when the component unmounts. Default true. A host
   * that persists the live items across remounts (e.g. content-composer's
   * carousel cache) sets this false and owns the final cleanup itself.
   */
  revokeOnUnmount?: boolean;
  /**
   * Whether an item may be edited. Images only by default; `openEditor` ignores
   * (with a dev warning) any item this refuses.
   */
  canEdit?: (item: MediaCarouselItem) => boolean;
}

export type { ApplyEditPatch };

export interface UseCarouselStateResult {
  items: MediaCarouselItem[];
  selectedId: string | null;
  editingId: string | null;
  selectedItem: MediaCarouselItem | null;
  editingItem: MediaCarouselItem | null;
  addItems: (next: MediaCarouselItem[]) => void;
  removeItem: (id: string) => void;
  reorder: (next: MediaCarouselItem[]) => void;
  select: (id: string | null) => void;
  openEditor: (id: string) => void;
  cancelEdit: () => void;
  applyEdit: (id: string, patch: ApplyEditPatch) => void;
  /** Merge a patch into one item (upload status, alt…). No-op for an unknown id. */
  updateItem: (id: string, patch: MediaCarouselItemPatch) => void;
  reset: () => void;
  /** The latest items, including changes made earlier in the same tick. Stable identity. */
  getItems: () => MediaCarouselItem[];
}

/** Only object URLs we created are ours to revoke; remote/consumer URLs aren't. */
function isOwnable(url: string): boolean {
  return url.startsWith("blob:");
}

/**
 * Owns the carousel model: a controllable `items` array (value/defaultValue/
 * onChange) plus internal `selectedId` / `editingId`, and the object-URL
 * lifecycle. `itemsRef` is updated SYNCHRONOUSLY inside every mutator (not via an
 * effect) so async/batched intakes can't read a stale base. An orphan-revoke
 * effect catches URLs dropped by any path — including a wholesale controlled
 * `value` swap (e.g. the host's `loadValue`) that bypasses removeItem.
 */
export function useCarouselState(
  opts: UseCarouselStateOptions,
): UseCarouselStateResult {
  const { maxItems, revokeOnUnmount = true } = opts;

  const [items, setItemsRaw] = useControllableState<MediaCarouselItem[]>({
    value: opts.value,
    defaultValue: opts.defaultValue ?? [],
    onChange: opts.onChange,
    componentName: "CarouselComposer",
    valuePropName: "value",
  });
  const [rawSelectedId, setSelectedId] = useState<string | null>(
    opts.value?.[0]?.id ?? opts.defaultValue?.[0]?.id ?? null,
  );
  const [editingId, setEditingId] = useState<string | null>(null);

  const selectedId =
    rawSelectedId != null && items.some((it) => it.id === rawSelectedId)
      ? rawSelectedId
      : (items[0]?.id ?? null);

  const cbRef = useRef<CarouselStateCallbacks & Pick<UseCarouselStateOptions, "canEdit">>(opts);
  useEffect(() => {
    cbRef.current = opts;
  });

  // itemsRef tracks committed render state; mutators below ALSO write it
  // synchronously so a second mutation in the same tick reads the latest base.
  const itemsRef = useRef(items);
  const selectedIdRef = useRef(selectedId);
  const editingIdRef = useRef(editingId);
  useEffect(() => {
    itemsRef.current = items;
    selectedIdRef.current = selectedId;
    editingIdRef.current = editingId;
  });
  const warnOnce = useWarnOnce();
  const getItems = useCallback(() => itemsRef.current, []);

  /** Synchronous-ref write + state set, so chained mutators compose correctly. */
  const setItems = useCallback(
    (next: MediaCarouselItem[]) => {
      itemsRef.current = next;
      setItemsRaw(next);
    },
    [setItemsRaw],
  );

  // Object-URL ownership. A URL is revoked by the orphan effect once it has been
  // committed in `items` at least once and then dropped. A URL the host has not
  // rendered yet (a controlled host that echoes `onChange` late) is never revoked
  // by an unrelated commit.
  const ownedUrls = useRef<Set<string>>(new Set());
  const seenUrls = useRef<Set<string>>(new Set());

  useEffect(() => {
    const present = new Set<string>();
    items.forEach((it) => {
      present.add(it.url);
      if (it.posterUrl) present.add(it.posterUrl);
    });
    present.forEach((u) => seenUrls.current.add(u));
    ownedUrls.current.forEach((u) => {
      if (!present.has(u) && seenUrls.current.has(u)) {
        URL.revokeObjectURL(u);
        ownedUrls.current.delete(u);
        seenUrls.current.delete(u);
      }
    });
  }, [items]);

  // Read at unmount time, so flipping the flag at runtime revokes nothing.
  const revokeOnUnmountRef = useRef(revokeOnUnmount);
  useEffect(() => {
    revokeOnUnmountRef.current = revokeOnUnmount;
  });
  useEffect(() => {
    const owned = ownedUrls.current;
    return () => {
      if (!revokeOnUnmountRef.current) return;
      owned.forEach((u) => URL.revokeObjectURL(u));
      owned.clear();
    };
  }, []);

  const addItems = useCallback(
    (incoming: MediaCarouselItem[]) => {
      if (incoming.length === 0) return;
      // Cap synchronously against the latest items (race-safe).
      const room = Math.max(0, maxItems - itemsRef.current.length);
      const toAdd = incoming.slice(0, room);
      const dropped = incoming.slice(room);
      // Revoke object URLs of items we won't keep (intake created them).
      dropped.forEach((it) => {
        if (isOwnable(it.url)) URL.revokeObjectURL(it.url);
        if (it.posterUrl && isOwnable(it.posterUrl)) {
          URL.revokeObjectURL(it.posterUrl);
        }
      });
      if (toAdd.length > 0) {
        toAdd.forEach((it) => {
          if (isOwnable(it.url)) ownedUrls.current.add(it.url);
          if (it.posterUrl && isOwnable(it.posterUrl)) {
            ownedUrls.current.add(it.posterUrl);
          }
        });
        setItems([...itemsRef.current, ...toAdd]);
        toAdd.forEach((it) => cbRef.current.onItemAdd?.(it));
      }
      if (dropped.length > 0) {
        cbRef.current.onMaxItemsExceeded?.(
          itemsRef.current.length + dropped.length,
          maxItems,
        );
      }
    },
    [maxItems, setItems],
  );

  const removeItem = useCallback(
    (id: string) => {
      const cur = itemsRef.current;
      const idx = cur.findIndex((it) => it.id === id);
      if (idx < 0) return;
      const next = cur.filter((it) => it.id !== id);
      setItems(next);
      cbRef.current.onItemRemove?.(id);
      if (selectedIdRef.current === id) {
        const neighbor = next[Math.min(idx, next.length - 1)] ?? null;
        const nid = neighbor?.id ?? null;
        setSelectedId(nid);
        cbRef.current.onSelect?.(nid);
      }
      if (editingIdRef.current === id) {
        editingIdRef.current = null;
        setEditingId(null);
        cbRef.current.onEditCancel?.(id);
      }
    },
    [setItems],
  );

  const reorder = useCallback(
    (next: MediaCarouselItem[]) => {
      setItems(next);
      cbRef.current.onReorder?.(next);
    },
    [setItems],
  );

  const select = useCallback((id: string | null) => {
    setSelectedId(id);
    cbRef.current.onSelect?.(id);
  }, []);

  const openEditor = useCallback((id: string) => {
    // Only images are editable — a video must never reach the editor, whose
    // export() would re-encode it.
    const target = itemsRef.current.find((it) => it.id === id);
    if (!target) return;
    if (target.kind !== "image") {
      if (process.env.NODE_ENV !== "production") {
        console.warn(
          `[CarouselComposer] openEditor("${id}") ignored: item is a ${target.kind}; only image items can be edited.`,
        );
      }
      return;
    }
    if (cbRef.current.canEdit?.(target) === false) {
      if (process.env.NODE_ENV !== "production") {
        console.warn(
          `[CarouselComposer] openEditor("${id}") ignored: canEditItem refused this item.`,
        );
      }
      return;
    }
    // Written now, not in a later effect: a Panel may call onCancel in its mount effect.
    editingIdRef.current = id;
    setSelectedId(id);
    setEditingId(id);
    cbRef.current.onEditOpen?.(id);
  }, []);

  const cancelEdit = useCallback(() => {
    const id = editingIdRef.current;
    if (id == null) return;
    editingIdRef.current = null;
    setEditingId(null);
    cbRef.current.onEditCancel?.(id);
  }, []);

  const applyEdit = useCallback(
    (id: string, patch: ApplyEditPatch) => {
      const cur = itemsRef.current;
      const idx = cur.findIndex((it) => it.id === id);
      if (editingIdRef.current !== id || idx < 0) {
        // Not the open edit (foreign id, unknown id, or a repeat after it closed).
        // A blob URL the panel minted for it would leak, so release it.
        const inUse = cur.some(
          (it) => it.url === patch.url || it.posterUrl === patch.url,
        );
        if (
          isOwnable(patch.url) &&
          !ownedUrls.current.has(patch.url) &&
          !inUse
        ) {
          URL.revokeObjectURL(patch.url);
        }
        warnOnce(
          "applyEdit-not-editing",
          `[CarouselComposer] onApply("${id}") ignored: that item is not the one being edited.`,
        );
        return;
      }
      const prev = cur[idx];
      if (isOwnable(patch.url)) ownedUrls.current.add(patch.url);
      // The edited media is not the uploaded one: drop the upload state. The host
      // re-uploads from onEditApply. The old URL is released by the orphan effect.
      const updated: MediaCarouselItem = {
        ...prev,
        url: patch.url,
        blob: patch.blob ?? prev.blob,
        editorState: patch.editorState ?? prev.editorState,
        sourceBlob: patch.sourceBlob ?? prev.sourceBlob,
        exportMeta: patch.exportMeta ?? prev.exportMeta,
        width: patch.width ?? prev.width,
        height: patch.height ?? prev.height,
      };
      delete updated.status;
      delete updated.progress;
      delete updated.error;
      setItems(cur.map((it, i) => (i === idx ? updated : it)));
      editingIdRef.current = null;
      setEditingId(null);
      cbRef.current.onEditApply?.(updated);
    },
    [setItems, warnOnce],
  );

  const updateItem = useCallback(
    (id: string, patch: MediaCarouselItemPatch) => {
      const cur = itemsRef.current;
      const idx = cur.findIndex((it) => it.id === id);
      if (idx < 0) return;
      const updated: MediaCarouselItem = { ...cur[idx], ...patch };
      // A new blob: URL from the host is the host's to revoke; the old owned one
      // is released by the orphan effect once it leaves `items`.
      setItems(cur.map((it, i) => (i === idx ? updated : it)));
    },
    [setItems],
  );

  const reset = useCallback(() => {
    ownedUrls.current.forEach((u) => URL.revokeObjectURL(u));
    ownedUrls.current.clear();
    setItems([]);
    setSelectedId(null);
    editingIdRef.current = null;
    setEditingId(null);
  }, [setItems]);

  const selectedItem = items.find((it) => it.id === selectedId) ?? null;
  const editingItem = items.find((it) => it.id === editingId) ?? null;

  return {
    items,
    selectedId,
    editingId,
    selectedItem,
    editingItem,
    addItems,
    removeItem,
    reorder,
    select,
    openEditor,
    cancelEdit,
    applyEdit,
    updateItem,
    reset,
    getItems,
  };
}

import { useCallback, useEffect, useRef, useState } from "react";

interface UseControllableStateOpts<T> {
  /** Controlled value. When provided, state is fully controlled by parent. */
  value?: T;
  /** Initial value for uncontrolled mode. */
  defaultValue: T;
  /** Fires on every state change (both modes). */
  onChange?: (next: T) => void;
  /** Component name used in dev warnings. */
  componentName: string;
  /** Prop name used in dev warnings (e.g., `"value"`). */
  valuePropName: string;
}

/**
 * Controlled+uncontrolled state-machine helper. Sealed local copy of the
 * library's standard generic (navigation/account-switcher + code-block) —
 * registry components can't share an app-level util beyond `@/lib/utils`, so
 * each procomp seals its own copy.
 *
 *   - Locks the controlled/uncontrolled mode based on the FIRST render's
 *     `value` and dev-warns when consumers flip modes mid-life.
 *   - Dev-warns when controlled mode is used without an `onChange` handler.
 *
 * Both warns tree-shake out of prod bundles.
 *
 * Internal helper — not exported from the procomp's public API.
 */
export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
  componentName,
  valuePropName,
}: UseControllableStateOpts<T>): readonly [T, (next: T) => void] {
  const [internal, setInternal] = useState<T>(defaultValue);
  const isControlled = value !== undefined;
  const onChangeRef = useRef(onChange);
  useEffect(() => {
    onChangeRef.current = onChange;
  });

  const wasControlledRef = useRef(isControlled);
  useEffect(() => {
    if (process.env.NODE_ENV === "production") return;
    if (wasControlledRef.current !== isControlled) {
      console.warn(
        `[${componentName}] \`${valuePropName}\` switched from ${
          wasControlledRef.current ? "controlled" : "uncontrolled"
        } to ${
          isControlled ? "controlled" : "uncontrolled"
        } mode. Components should not switch modes mid-life; pick one at mount.`,
      );
      wasControlledRef.current = isControlled;
    }
  }, [isControlled, componentName, valuePropName]);

  useEffect(() => {
    if (process.env.NODE_ENV === "production") return;
    if (isControlled && !onChangeRef.current) {
      const capitalized =
        valuePropName.charAt(0).toUpperCase() + valuePropName.slice(1);
      console.warn(
        `[${componentName}] \`${valuePropName}\` is controlled but no onChange handler was provided. ` +
          `State will appear frozen. Pass \`on${capitalized}Change\` ` +
          `(or use the uncontrolled variant by passing \`default${capitalized}\` instead).`,
      );
    }
  }, [isControlled, componentName, valuePropName]);

  const current = isControlled ? (value as T) : internal;

  const set = useCallback(
    (next: T) => {
      if (!isControlled) setInternal(next);
      onChangeRef.current?.(next);
    },
    [isControlled],
  );

  return [current, set] as const;
}

"use client";

import { useEffect, useLayoutEffect, useState } from "react";

const useIsoLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

export type Direction = "ltr" | "rtl";

/**
 * Resolves text direction (consumer contract C4 / R6): the `dir` prop wins; otherwise the
 * element's direction, read after mount — the computed `direction`, or the nearest explicit
 * non-`auto` `[dir]` ancestor (jsdom has no UA stylesheet for `dir`); otherwise `"ltr"`.
 *
 * The server render and the first client render both return the prop or `"ltr"`, so markup
 * must not depend on the resolved value before mount. Key handling, swipe, carousel and
 * transition logic may. A later direction change is not observed — pass `dir` if the app
 * switches direction at runtime without remounting.
 *
 * Directional props take `"start" | "end"`; physical values stay only as deprecated aliases.
 * Copy into a component's `hooks/`. Canonical copy: `_template/_snippets/` (tests next to it).
 */
export function useDirection(
  ref: React.RefObject<HTMLElement | null>,
  dirProp?: Direction,
): Direction {
  const [resolved, setResolved] = useState<Direction>("ltr");
  useIsoLayoutEffect(() => {
    if (dirProp) return;
    const el = ref.current;
    if (!el) return;
    const explicit = el.closest('[dir]:not([dir="auto"])')?.getAttribute("dir")?.toLowerCase();
    const rtl = getComputedStyle(el).direction === "rtl" || explicit === "rtl";
    setResolved(rtl ? "rtl" : "ltr");
  }, [dirProp, ref]);
  return dirProp ?? resolved;
}

